package canonical

import (
	"bytes"
	"encoding/json"
	"os"
	"testing"
)

func decode(t *testing.T, raw json.RawMessage) any {
	t.Helper()
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.UseNumber()
	var v any
	if err := dec.Decode(&v); err != nil {
		t.Fatal(err)
	}
	return v
}

// The golden vectors are generated by Python's json.dumps and shared by every
// implementation: Python, TypeScript, Rust and now Go.
func TestReproducesEveryGoldenVectorByteForByte(t *testing.T) {
	raw, err := os.ReadFile("../../../contracts/conformance/canonical-vectors.json")
	if err != nil {
		t.Fatal(err)
	}
	var doc struct {
		Vectors []struct {
			Name      string          `json:"name"`
			Input     json.RawMessage `json:"input"`
			Canonical string          `json:"canonical"`
		} `json:"vectors"`
	}
	if err := json.Unmarshal(raw, &doc); err != nil {
		t.Fatal(err)
	}
	if len(doc.Vectors) < 12 {
		t.Fatalf("only %d vectors", len(doc.Vectors))
	}
	for _, v := range doc.Vectors {
		got, err := JSON(decode(t, v.Input))
		if err != nil {
			t.Fatalf("%s: %v", v.Name, err)
		}
		if got != v.Canonical {
			t.Errorf("%s:\n got  %s\n want %s", v.Name, got, v.Canonical)
		}
	}
}

func TestFloatsAreRefused(t *testing.T) {
	for _, in := range []string{`{"a":1.5}`, `{"a":1e400}`, `{"a":[0.1]}`} {
		if _, err := JSON(decode(t, json.RawMessage(in))); err == nil {
			t.Errorf("%s should be refused", in)
		}
	}
	// an integral float is the same document as the integer
	got, err := JSON(decode(t, json.RawMessage(`{"a":3.0}`)))
	if err != nil || got != `{"a":3}` {
		t.Errorf("got %q, %v", got, err)
	}
}

func TestEdgeCases(t *testing.T) {
	cases := map[string]string{
		`{"b":1,"a":{"z":[],"y":{}},"c":[]}`: `{"b":1}`, // pruned bottom-up: "a" becomes {} and is then dropped itself
		`{"s":"\u007f"}`:                     `{"s":"\u007f"}`,
		`{"s":"é😀"}`:                         `{"s":"\u00e9\ud83d\ude00"}`,
		`{"a":[[],{}]}`:                      `{"a":[[],{}]}`, // empties inside arrays stay
		`{"n":null,"t":true}`:                `{"n":null,"t":true}`,
	}
	for in, want := range cases {
		got, err := JSON(decode(t, json.RawMessage(in)))
		if err != nil {
			t.Errorf("%s: %v", in, err)
			continue
		}
		if got != want {
			t.Errorf("%s:\n got  %s\n want %s", in, got, want)
		}
	}
}
